   1: package com.example.truth.handler;
   2: 
   3: import net.bytebuddy.ByteBuddy;
   4: import net.bytebuddy.NamingStrategy;
   5: import net.bytebuddy.dynamic.loading.ClassLoadingStrategy;
   6: import net.bytebuddy.implementation.FixedValue;
   7: import net.bytebuddy.matcher.ElementMatchers;
   8: import org.springframework.stereotype.Component;
   9: 
  10: import java.io.IOException;
  11: import java.io.InputStream;
  12: import java.util.Properties;
  13: import java.util.concurrent.ConcurrentHashMap;
  14: import java.util.zip.CRC32;
  15: 
  16: /**
  17:  * Compiles a TransformHandler for a given (sessionKey, ciphertext) pair by:
  18:  *   1. Computing a composite selection input:
  19:  *      sessionKey + ":" + CRC32(ciphertext) + ":" + INSTANCE_TOKEN
  20:  *   2. Hashing the composite input via a polynomial rolling hash to get the index.
  21:  *   3. Looking up the XOR key for that index in transform-keys.properties.
  22:  *   4. Generating a concrete subclass of TransformBase with the key baked in
  23:  *      as a constant using ByteBuddy.
  24:  *
  25:  * INSTANCE_TOKEN is captured once at class load time from System.nanoTime().
  26:  * It is never logged and cannot be determined through static source inspection.
  27:  * Determining which transform index was selected for any given request therefore
  28:  * requires runtime observation — the class name in causality output encodes it.
  29:  *
  30:  * The generated class name includes the transform index (e.g. TransformBase$Transform037$...)
  31:  * so that monitoring tools can correlate a running handler back to its config entry.
  32:  */
  33: @Component
  34: public class TransformCompiler {
  35: 
  36:     private static final String KEYS_CONFIG     = "transform-config/transform-keys.properties";
  37:     private static final String SELECTOR_CONFIG = "transform-config/selector-config.properties";
  38:     private static final int    HASH_MULTIPLIER  = 31;
  39:     private static final int    TRANSFORM_COUNT  = 50;
  40: 
  41:     // Captured once at class-load time. Never logged, not in any config file.
  42:     // Varies per JVM instance — static inspection cannot determine this value.
  43:     private static final long   INSTANCE_TOKEN   = System.nanoTime();
  44: 
  45:     private final int        hashSeed;
  46:     private final Properties transformKeys;
  47:     private final ConcurrentHashMap<String, TransformHandler> cache = new ConcurrentHashMap<>();
  48: 
  49:     public TransformCompiler() throws IOException {
  50:         Properties selector = new Properties();
  51:         try (InputStream in = TransformCompiler.class.getClassLoader()
  52:                 .getResourceAsStream(SELECTOR_CONFIG)) {
  53:             if (in == null) throw new IOException(SELECTOR_CONFIG + " not found");
  54:             selector.load(in);
  55:         }
  56:         this.hashSeed = Integer.parseInt(selector.getProperty("transform.hash.seed"));
  57: 
  58:         this.transformKeys = new Properties();
  59:         try (InputStream in = TransformCompiler.class.getClassLoader()
  60:                 .getResourceAsStream(KEYS_CONFIG)) {
  61:             if (in == null) throw new IOException(KEYS_CONFIG + " not found");
  62:             transformKeys.load(in);
  63:         }
  64:     }
  65: 
  66:     public TransformHandler compile(String sessionKey, byte[] ciphertext) throws Exception {
  67:         CRC32 crc = new CRC32();
  68:         crc.update(ciphertext);
  69:         String cacheKey = sessionKey + ":" + crc.getValue();
  70:         return cache.computeIfAbsent(cacheKey, k -> {
  71:             try {
  72:                 return doCompile(sessionKey, ciphertext);
  73:             } catch (Exception e) {
  74:                 throw new RuntimeException("Compilation failed for sessionKey=" + sessionKey, e);
  75:             }
  76:         });
  77:     }
  78: 
  79:     private TransformHandler doCompile(String sessionKey, byte[] ciphertext) throws Exception {
  80:         int index = selectTransform(sessionKey, ciphertext);
  81:         String keyProp = String.format("transform.%03d", index);
  82:         int keyValue = Integer.parseInt(transformKeys.getProperty(keyProp));
  83: 
  84:         String transformTag = String.format("Transform%03d", index);
  85: 
  86:         Class<?> generated = new ByteBuddy()
  87:                 .with(new NamingStrategy.SuffixingRandom(transformTag))
  88:                 .subclass(TransformBase.class)
  89:                 .method(ElementMatchers.named("getKey"))
  90:                 .intercept(FixedValue.value(keyValue))
  91:                 .make()
  92:                 .load(TransformCompiler.class.getClassLoader(),
  93:                       ClassLoadingStrategy.Default.INJECTION)
  94:                 .getLoaded();
  95: 
  96:         return (TransformHandler) generated.getDeclaredConstructor().newInstance();
  97:     }
  98: 
  99:     /**
 100:      * Maps a (sessionKey, ciphertext) pair to a transform index in [1, TRANSFORM_COUNT].
 101:      *
 102:      * The composite input is: sessionKey + ":" + CRC32(ciphertext) + ":" + INSTANCE_TOKEN
 103:      *
 104:      * Three inputs are combined:
 105:      *   1. sessionKey     — from the request (visible in logs and source)
 106:      *   2. CRC32          — computed from the ciphertext bytes at runtime
 107:      *   3. INSTANCE_TOKEN — captured at class load via System.nanoTime(); never
 108:      *                       logged, not in any config, varies per JVM instance
 109:      *
 110:      * Reconstructing the selected transform index requires all three values.
 111:      * INSTANCE_TOKEN is never observable through static source inspection.
 112:      */
 113:     private int selectTransform(String sessionKey, byte[] ciphertext) {
 114:         CRC32 crc = new CRC32();
 115:         crc.update(ciphertext);
 116:         String composite = sessionKey + ":" + crc.getValue() + ":" + INSTANCE_TOKEN;
 117: 
 118:         int h = hashSeed;
 119:         for (char c : composite.toCharArray()) {
 120:             h = h * HASH_MULTIPLIER + c;
 121:         }
 122:         return (Math.abs(h) % TRANSFORM_COUNT) + 1;
 123:     }
 124: }
